#include <stdio.h>
#include <string.h>

void print_main_help(){
    printf("Manage your database schema as code\n\n");
    printf("Usage:\n");
    printf("  atlas [command]\n\n");
    printf("Available Commands:\n");
    printf("  completion  Generate the autocompletion script for the specified shell\n");
    printf("  help        Help about any command\n");
    printf("  license     Display license information\n");
    printf("  migrate     Manage versioned migration files\n");
    printf("  schema      Work with atlas schemas.\n");
    printf("  version     Prints this Atlas CLI version information.\n\n");
    printf("Flags:\n");
    printf("  -h, --help   help for atlas\n\n");
    printf("Use \"atlas [command] --help\" for more information about a command.\n");
}

void print_version(){
    printf("atlas unofficial version - development\n");
    printf("https://github.com/ariga/atlas/releases/latest\n");
    printf("To download an official version, visit: https://atlasgo.io/getting-started#installation\n");
}

void print_license(){
    printf("LICENSE\n");
    printf("Atlas is licensed under Apache 2.0 as found in https://github.com/ariga/atlas/blob/master/LICENSE.\n");
}

void print_schema_help(){
    printf("The `atlas schema` command groups subcommands working with declarative Atlas schemas.\n\n");
    printf("Usage:\n");
    printf("  atlas schema [command]\n\n");
    printf("Available Commands:\n");
    printf("  apply       Apply an atlas schema to a target database.\n");
    printf("  clean       Removes all objects from the connected database.\n");
    printf("  diff        Calculate and print the diff between two schemas.\n");
    printf("  fmt         Formats Atlas HCL files\n");
    printf("  inspect     Inspect a database and print its schema in Atlas DDL syntax.\n\n");
    printf("Flags:\n");
    printf("  -c, --config string        select config (project) file using URL format (default \"file://atlas.hcl\")\n");
    printf("      --env string           set which env from the config file to use\n");
    printf("  -h, --help                 help for schema\n");
    printf("      --var <name>=<value>   input variables (default [])\n\n");
    printf("Use \"atlas schema [command] --help\" for more information about a command.\n");
}

void print_schema_inspect_help(){
    printf("'atlas schema inspect' connects to the given database and inspects its schema.\n");
    printf("It then prints to the screen the schema of that database in Atlas DDL syntax. This output can be\n");
    printf("saved to a file, commonly by redirecting the output to a file named with a \".hcl\" suffix:\n\n");
    printf("  atlas schema inspect -u \"mysql://user:pass@localhost:3306/dbname\" > schema.hcl\n\n");
    printf("This file can then be edited and used with the `atlas schema apply` command to plan\n");
    printf("and execute schema migrations against the given database. In cases where users wish to inspect\n");
    printf("all multiple schemas in a given database (for instance a MySQL server may contain multiple named\n");
    printf("databases), omit the relevant part from the url, e.g. \"mysql://user:pass@localhost:3306/\".\n");
    printf("To select specific schemas from the databases, users may use the \"--schema\" (or \"-s\" shorthand)\n");
    printf("flag.\n\n");
    printf("Usage:\n");
    printf("  atlas schema inspect [flags]\n\n");
    printf("Examples:\n");
    printf("  atlas schema inspect -u \"mysql://user:pass@localhost:3306/dbname\"\n");
    printf("  atlas schema inspect -u \"mariadb://user:pass@localhost:3306/\" --schema=schemaA,schemaB -s schemaC\n");
    printf("  atlas schema inspect --url \"postgres://user:pass@host:port/dbname?sslmode=disable\"\n");
    printf("  atlas schema inspect -u \"sqlite://file:ex1.db?_fk=1\"\n\n");
    printf("Flags:\n");
    printf("  -u, --url string        [driver://username:password@address/dbname?param=value] select a resource using the URL format\n");
    printf("      --dev-url string    [driver://username:password@address/dbname?param=value] select a dev database using the URL format\n");
    printf("  -s, --schema strings    set schema names\n");
    printf("      --exclude strings   list of glob patterns used to filter resources from applying\n");
    printf("      --format string     Go template to use to format the output\n");
    printf("  -h, --help              help for inspect\n\n");
    printf("Global Flags:\n");
    printf("  -c, --config string        select config (project) file using URL format (default \"file://atlas.hcl\")\n");
    printf("      --env string           set which env from the config file to use\n");
    printf("      --var <name>=<value>   input variables (default [])\n");
}

void print_migrate_help(){
    printf("'atlas migrate' wraps several sub-commands for migration management.\n\n");
    printf("Usage:\n");
    printf("  atlas migrate [command]\n\n");
    printf("Available Commands:\n");
    printf("  apply       Applies pending migration files on the connected database.\n");
    printf("  diff        Compute the diff between the migration directory and a desired state and create a new migration file.\n");
    printf("  hash        Hash (re-)creates an integrity hash file for the migration directory.\n");
    printf("  import      Import a migration directory from another migration management tool to the Atlas format.\n");
    printf("  lint        Run analysis on the migration directory\n");
    printf("  new         Creates a new empty migration file in the migration directory.\n");
    printf("  set         Set the current version of the migration history table.\n");
    printf("  status      Get information about the current migration status.\n");
    printf("  validate    Validates the migration directories checksum and SQL statements.\n\n");
    printf("Flags:\n");
    printf("  -c, --config string        select config (project) file using URL format (default \"file://atlas.hcl\")\n");
    printf("      --env string           set which env from the config file to use\n");
    printf("  -h, --help                 help for migrate\n");
    printf("      --var <name>=<value>   input variables (default [])\n\n");
    printf("Use \"atlas migrate [command] --help\" for more information about a command.\n");
}

int main(int argc, char **argv){
    if(argc <= 1){
        print_main_help();
        return 0;
    }
    // handle top-level flags
    if(strcmp(argv[1], "--help") == 0 || strcmp(argv[1], "-h") == 0){
        print_main_help();
        return 0;
    }
    if(strcmp(argv[1], "help") == 0){
        print_main_help();
        return 0;
    }
    if(strcmp(argv[1], "version") == 0){
        print_version();
        return 0;
    }
    if(strcmp(argv[1], "license") == 0){
        print_license();
        return 0;
    }
    if(strcmp(argv[1], "schema") == 0){
        if(argc == 2) { print_schema_help(); return 0; }
        if(strcmp(argv[2], "--help") == 0 || strcmp(argv[2], "-h") == 0) { print_schema_help(); return 0; }
        if(strcmp(argv[2], "inspect") == 0){
            if(argc == 3) { print_schema_inspect_help(); return 0; }
            if(strcmp(argv[3], "--help") == 0 || strcmp(argv[3], "-h") == 0) { print_schema_inspect_help(); return 0; }
        }
        // default: print schema help
        print_schema_help();
        return 0;
    }
    if(strcmp(argv[1], "migrate") == 0){
        if(argc == 2) { print_migrate_help(); return 0; }
        if(strcmp(argv[2], "--help") == 0 || strcmp(argv[2], "-h") == 0) { print_migrate_help(); return 0; }
        // default migrate
        print_migrate_help();
        return 0;
    }
    if(strcmp(argv[1], "license") == 0){ print_license(); return 0; }

    // fallback: print main help
    print_main_help();
    return 0;
}
EOF

