# add executable to .gitignore if not present
if ! grep -q "^executable$" .gitignore 2>/dev/null; then
  echo "executable" >> .gitignore
fi

# compile to test
./compile.sh

# test a few commands
./executable --help > /tmp/help.out
./executable version > /tmp/version.out
./executable license > /tmp/license.out

printf "-----HELP-----\n"
cat /tmp/help.out
printf "-----VERSION-----\n"
cat /tmp/version.out
printf "-----LICENSE-----\n"
cat /tmp/license.out
"}

